import io
import unittest
from exporter import export

class ExportTest(unittest.TestCase):
    def test_columns(self):
        stream = io.StringIO()
        export([{'item_id': 1, 'label': 'A', 'quantity': '2.0'}], stream)
        self.assertEqual(stream.getvalue().splitlines(), ['item_id,label,quantity', '1,A,2.0'])

if __name__ == '__main__':
    unittest.main()
